"use client";

import { motion, useReducedMotion, type Transition } from "motion/react";
import { type ComponentPropsWithoutRef, useState } from "react";

import { cn } from "@/lib/utils";

/** Props for a switch. Pass `checked` to control it, or `defaultChecked` to let it hold its own state. */
export type SwitchProps = Omit<ComponentPropsWithoutRef<"button">, "onChange" | "children"> & {
  checked?: boolean;
  defaultChecked?: boolean;
  onCheckedChange?: (checked: boolean) => void;
};

// Critically damped, like every state change the system confirms.
const SPRING: Transition = { type: "spring", stiffness: 600, damping: 49, mass: 1 };
const INSTANT: Transition = { duration: 0 };
// The thumb is 20px wide in a 44px track with 2px padding on each side.
const TRAVEL = 20;
const STRETCH = 1.2;

/**
 * Turns one setting on or off. The thumb stretches toward its destination
 * while pressed, then springs across when released.
 */
export function Switch({
  checked,
  defaultChecked = false,
  onCheckedChange,
  className,
  disabled,
  onClick,
  onPointerDown,
  onPointerUp,
  onPointerLeave,
  onPointerCancel,
  ...buttonProps
}: SwitchProps) {
  const [ownChecked, setOwnChecked] = useState(defaultChecked);
  const [pressed, setPressed] = useState(false);
  const on = checked ?? ownChecked;
  const reduceMotion = useReducedMotion();

  const toggle = () => {
    if (checked === undefined) setOwnChecked(!on);
    onCheckedChange?.(!on);
  };

  return (
    <button
      {...buttonProps}
      type="button"
      role="switch"
      aria-checked={on}
      disabled={disabled}
      onClick={(event) => {
        onClick?.(event);
        if (!event.defaultPrevented) toggle();
      }}
      onPointerDown={(event) => {
        onPointerDown?.(event);
        setPressed(true);
      }}
      onPointerUp={(event) => {
        onPointerUp?.(event);
        setPressed(false);
      }}
      onPointerLeave={(event) => {
        onPointerLeave?.(event);
        setPressed(false);
      }}
      onPointerCancel={(event) => {
        onPointerCancel?.(event);
        setPressed(false);
      }}
      className={cn(
        // The track is 24px tall; the pseudo-element grows the hit area to 44px.
        "relative inline-flex h-6 w-11 shrink-0 cursor-pointer touch-manipulation items-center rounded-full p-0.5 outline-none",
        "before:absolute before:-inset-y-2.5 before:inset-x-0",
        "motion-safe:transition-colors motion-safe:duration-200",
        "focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background",
        "disabled:cursor-not-allowed disabled:opacity-50",
        on ? "bg-primary" : "bg-muted-foreground/40",
        className,
      )}
    >
      <motion.span
        aria-hidden="true"
        initial={false}
        animate={{ x: on ? TRAVEL : 0, scaleX: pressed && !reduceMotion ? STRETCH : 1 }}
        transition={reduceMotion ? INSTANT : SPRING}
        // The stretch grows toward the side the thumb will travel to, so the
        // press reads as the start of the move rather than a swell in place.
        className={cn("block size-5 rounded-full bg-background shadow-sm", on ? "origin-right" : "origin-left")}
      />
    </button>
  );
}
